// Single scratch ticket — canvas-based silver layer with drag-to-erase
const ScratchTicket = ({
  ticket,
  isRevealed,
  isUsed,
  isFinal = false,
  onReveal,
  onUse,
}) => {
  const canvasRef = useRef(null);
  const isScratchingRef = useRef(false);
  const lastCheckRef = useRef(0);
  const autoUseScheduledRef = useRef(false);

  const cssWidth = isFinal ? 320 : 240;
  const cssHeight = isFinal ? 150 : 120;

  useEffect(() => {
    if (isRevealed) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const dpr = window.devicePixelRatio || 1;
    canvas.width = cssWidth * dpr;
    canvas.height = cssHeight * dpr;
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;

    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // Silver gradient
    const gradient = ctx.createLinearGradient(0, 0, cssWidth, cssHeight);
    gradient.addColorStop(0, '#D8D8D8');
    gradient.addColorStop(0.5, '#F0F0F0');
    gradient.addColorStop(1, '#B8B8B8');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, cssWidth, cssHeight);

    // Subtle noise on the silver
    for (let i = 0; i < 400; i++) {
      const v = 100 + Math.random() * 130;
      ctx.fillStyle = `rgba(${v}, ${v}, ${v}, ${Math.random() * 0.18})`;
      ctx.fillRect(Math.random() * cssWidth, Math.random() * cssHeight, 2, 2);
    }

    // A faint diagonal sheen line
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, cssHeight * 0.3);
    ctx.lineTo(cssWidth, cssHeight * 0.1);
    ctx.stroke();

    // "SCRATCH HERE" text
    ctx.fillStyle = '#555';
    ctx.font = `bold 14px 'Special Elite', 'Courier New', monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('SCRATCH HERE', cssWidth / 2, cssHeight / 2 - 6);
    ctx.font = `10px 'Special Elite', 'Courier New', monospace`;
    ctx.fillText('to reveal', cssWidth / 2, cssHeight / 2 + 12);
  }, [isRevealed, cssWidth, cssHeight]);

  const scratch = (x, y) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.beginPath();
    ctx.arc(x, y, 22, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Throttled progress check
    const now = Date.now();
    if (now - lastCheckRef.current < 120) return;
    lastCheckRef.current = now;

    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    let transparent = 0;
    const step = 4 * 60;
    for (let i = 3; i < imageData.data.length; i += step) {
      if (imageData.data[i] === 0) transparent++;
    }
    const total = imageData.data.length / step;
    const pct = transparent / total;
    if (pct > 0.45 && !isRevealed) {
      onReveal(ticket.id);
      // Auto-mark non-final tickets as used IMMEDIATELY when revealed
      // — scratch is the only action needed, no second tap.
      if (!isFinal && onUse && !autoUseScheduledRef.current && !isUsed) {
        autoUseScheduledRef.current = true;
        onUse(ticket.id);
      }
    }
  };

  const getPos = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const scaleX = (canvas.width / dpr) / rect.width;
    const scaleY = (canvas.height / dpr) / rect.height;
    if (e.touches && e.touches[0]) {
      return {
        x: (e.touches[0].clientX - rect.left) * scaleX,
        y: (e.touches[0].clientY - rect.top) * scaleY,
      };
    }
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY,
    };
  };

  const handleStart = (e) => {
    e.preventDefault();
    isScratchingRef.current = true;
    const pos = getPos(e);
    scratch(pos.x, pos.y);
  };

  const handleMove = (e) => {
    if (!isScratchingRef.current) return;
    e.preventDefault();
    const pos = getPos(e);
    scratch(pos.x, pos.y);
  };

  const handleEnd = () => {
    isScratchingRef.current = false;
  };

  const handleClick = () => {
    if (isRevealed && !isUsed && onUse) onUse(ticket.id);
  };

  return (
    <div
      onClick={handleClick}
      style={{
        ...styles.ticketWrapper,
        width: `${cssWidth}px`,
        height: `${cssHeight}px`,
        cursor: isRevealed ? (isUsed ? 'default' : 'pointer') : 'crosshair',
        opacity: isUsed && !isFinal ? 0.55 : 1,
        transition: 'opacity 0.4s ease',
      }}
    >
      {/* Ticket content (always rendered) */}
      <div style={styles.ticketInner}>
        <TicketSVG ticket={ticket} isFinal={isFinal} />
        {isUsed && !isFinal && <UsedStamp w={cssWidth} h={cssHeight} />}
      </div>

      {/* Scratch layer (canvas) — only when not revealed */}
      {!isRevealed && (
        <canvas
          ref={canvasRef}
          style={{
            position: 'absolute',
            inset: 0,
            cursor: 'crosshair',
            borderRadius: '2px',
            touchAction: 'none',
          }}
          onMouseDown={handleStart}
          onMouseMove={handleMove}
          onMouseUp={handleEnd}
          onMouseLeave={handleEnd}
          onTouchStart={handleStart}
          onTouchMove={handleMove}
          onTouchEnd={handleEnd}
        />
      )}
    </div>
  );
};

const SeventhMonthversary = () => {
  const [now, setNow] = useState(new Date());
  const [scratchedIds, setScratchedIds] = useState([]);
  const [usedIds, setUsedIds] = useState([]);
  const [showFinal, setShowFinal] = useState(false);
  const [finalRevealed, setFinalRevealed] = useState(false);
  const [showMessage, setShowMessage] = useState(false);
  const musicUnlocked = useRef(false);

  const isLocked = now < UNLOCK_DATE;

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!document.getElementById('monthversary-fonts')) {
      const link = document.createElement('link');
      link.id = 'monthversary-fonts';
      link.href = 'https://fonts.googleapis.com/css2?family=Caveat:wght@400;500;600;700&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600;1,700&family=Special+Elite&display=swap';
      link.rel = 'stylesheet';
      document.head.appendChild(link);
    }
  }, []);

  // Music fallback — dispatch the unlock on every user interaction,
  // not just the first. MusicPlayer retries the play() call each time,
  // so if the audio file is in place, every tap is another chance.
  useEffect(() => {
    const triggerMusic = () => {
      musicUnlocked.current = true;
      window.dispatchEvent(new Event(TICKET_UNLOCK_EVENT));
    };
    window.addEventListener('mousedown', triggerMusic, { passive: true });
    window.addEventListener('touchstart', triggerMusic, { passive: true });
    window.addEventListener('click', triggerMusic, { passive: true });
    return () => {
      window.removeEventListener('mousedown', triggerMusic);
      window.removeEventListener('touchstart', triggerMusic);
      window.removeEventListener('click', triggerMusic);
    };
  }, []);

  const handleReveal = (id) => {
    if (!scratchedIds.includes(id)) {
      if (!musicUnlocked.current) {
        musicUnlocked.current = true;
        window.dispatchEvent(new Event(TICKET_UNLOCK_EVENT));
      }
      setScratchedIds((prev) => [...prev, id]);
    }
  };

  const handleUse = (id) => {
    if (!usedIds.includes(id)) {
      const newUsed = [...usedIds, id];
      setUsedIds(newUsed);
      if (newUsed.length === 7) {
        // Short breath so the last USED stamp animation can play
        setTimeout(() => setShowFinal(true), 500);
      }
    }
  };

  const handleFinalReveal = () => {
    if (finalRevealed) return;
    setFinalRevealed(true);
    // Delay the final message so she has time to read the ticket first
    setTimeout(() => setShowMessage(true), 2200);
  };

  // ── COUNTDOWN ──
  if (isLocked) {
    const diff = UNLOCK_DATE - now;
    const days = Math.max(0, Math.floor(diff / (1000 * 60 * 60 * 24)));
    const hours = Math.max(0, Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)));
    const minutes = Math.max(0, Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60)));
    const seconds = Math.max(0, Math.floor((diff % (1000 * 60)) / 1000));

    return (
      <div style={styles.page}>
        <div style={styles.countdownWrapper}>
          <p style={styles.countdownLabel}>7th monthversary</p>
          <h1 style={styles.countdownTitle}>The Ticket Stand</h1>
          <Flourish />
          <p style={styles.countdownSub}>The doors open on September 26</p>
          <div style={styles.countdownTimer}>
            {[
              { value: days, label: 'days' },
              { value: hours, label: 'hrs' },
              { value: minutes, label: 'min' },
              { value: seconds, label: 'sec' },
            ].map((unit) => (
              <div key={unit.label} style={styles.countdownUnit}>
                <span style={styles.countdownValue}>{unit.value}</span>
                <span style={styles.countdownLabelSmall}>{unit.label}</span>
              </div>
            ))}
          </div>
          <p style={styles.countdownHint}>Seven tickets are waiting to be scratched.</p>
        </div>
      </div>
    );
  }

  // ── MAIN ──
  const allUsed = usedIds.length === 7;

  return (
    <div style={styles.page}>
      {/* ── HEADER ── */}
      {!showMessage && (
        <div style={styles.headerWrapper}>
          <p style={styles.topLabel}>7th monthversary</p>
          <h1 style={styles.sceneTitle}>The Ticket Stand</h1>
          <Flourish />
          <p style={styles.sceneSubtitle}>
            Seven small notes for the seven months we've shared.
            Scratch each one to read what's tucked inside.
          </p>
        </div>
      )}

      {/* ── PROGRESS ── */}
      {!showMessage && !showFinal && (
        <div style={styles.progressRow}>
          <span style={styles.progressText}>
            {usedIds.length} of 7 used
          </span>
        </div>
      )}

      {/* ── TICKETS GRID ── */}
      {!showFinal && !showMessage && (
        <div style={styles.ticketsGrid}>
          {tickets.map((ticket) => (
            <ScratchTicket
              key={ticket.id}
              ticket={ticket}
              isRevealed={scratchedIds.includes(ticket.id)}
              isUsed={usedIds.includes(ticket.id)}
              onReveal={handleReveal}
              onUse={handleUse}
            />
          ))}
        </div>
      )}

      {/* ── FINAL TICKET (stays visible — message fades in BELOW after delay) ── */}
      {showFinal && !showMessage && !finalRevealed && (
        <div style={styles.finalWrap}>
          <p style={styles.finalHint}>One last ticket — for the next 7 months.</p>
          <ScratchTicket
            ticket={finalTicket}
            isRevealed={false}
            isUsed={false}
            isFinal
            onReveal={handleFinalReveal}
            onUse={() => {}}
          />
          <p style={styles.finalTapHint}>drag your finger across the silver</p>
        </div>
      )}

      {/* ── FINAL LETTER (shown after the 8th ticket is scratched) ── */}
      {finalRevealed && (
        <div style={styles.letterWrap} className="message-rise">
          <p style={styles.letterBadge}>7 months of us</p>
          <h1 style={styles.letterTitle}>Happy 7th Monthversary</h1>

          <div style={styles.letterCardOuter}>
            <TornTop />
            <div style={styles.letterCard}>
              <p style={styles.letterDate}>Sept 26, 2026</p>
            <p style={styles.letterPara}>
              Seven tickets. All of them yours. Seven small notes from the seven months we have shared, and the seven I hope we still will.
            </p>
            <p style={styles.letterPara}>
              Somewhere between the first and the last, I stopped counting the months. I started counting the reasons instead. The way you laugh at nothing. The way you say goodnight like it is the easiest thing in the world. The way you always show up — across every mile, every timezone, every time I needed you most.
            </p>
            <p style={styles.letterHighlight}>
              Admit one. That's you. The rest of this story is whatever we make of it.
            </p>
            <p style={styles.letterPara}>
              Seven months down. A lifetime of yes still to come. I will keep choosing you — the way a person keeps choosing the same person every morning, not because they have to, but because they never want to stop.
            </p>
            <div style={styles.letterSignature}>
              <p style={styles.letterSigLine}>Yours, across every mile,</p>
              <p style={styles.letterSigName}>— Gagas</p>
            </div>
          </div>
          </div>

          <p style={styles.letterFooter}>
            Seven tickets. Seven months. Many more to come.
          </p>
        </div>
      )}

      <MusicPlayer
        playlist={playlist}
        loop={true}
        autoplayOnMount={false}
        unlockEventName={TICKET_UNLOCK_EVENT}
        showPromptUi={false}
      />

      <style>{`
        @keyframes fadeUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes fadeIn  { from { opacity: 0; } to { opacity: 1; } }
        @keyframes ticketSway {
          0%, 100% { transform: rotate(-0.4deg) translateY(0); }
          50%      { transform: rotate(0.4deg) translateY(-2px); }
        }
        @keyframes finalIn {
          0%   { opacity: 0; transform: translateY(40px) scale(0.92); }
          100% { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes messageRise {
          0%   { opacity: 0; transform: translateY(30px); }
          100% { opacity: 1; transform: translateY(0); }
        }
        @keyframes stampPress {
          0%   { opacity: 0; transform: scale(1.6) rotate(-22deg); }
          60%  { opacity: 0.85; transform: scale(0.94) rotate(-15deg); }
          100% { opacity: 0.75; transform: scale(1) rotate(-15deg); }
        }

        .ticket-float {
          animation: ticketSway 5s ease-in-out infinite;
          transform-origin: center;
        }
        .final-in {
          animation: finalIn 1.1s cubic-bezier(0.34, 1.56, 0.64, 1) both;
        }
        .message-rise {
          animation: messageRise 1.2s cubic-bezier(0.16, 1, 0.3, 1) both;
        }
        .used-stamp-anim {
          animation: stampPress 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) both;
          transform-origin: center;
        }
      `}</style>
    </div>
  );
};

